use std::collections::HashSet;

/// Return a new vector with duplicates removed.
/// - The result contains no duplicates.
/// - The set of elements in the result equals the set of elements in the input.
///
/// Order is preserved (first occurrence kept).
pub fn remove_duplicates(nums: Vec<i32>) -> Vec<i32> {
    let mut seen: HashSet<i32> = HashSet::with_capacity(nums.len());
    let mut res: Vec<i32> = Vec::with_capacity(nums.len());

    for x in nums {
        if seen.insert(x) {
            res.push(x);
        }
    }
    res
}